import fs from 'fs';
import path from 'path';

const DELAY_MS = 1200;
const LIST_URL = 'https://prod.danawa.com/list/ajax/getProductList.ajax.php';
const DETAIL_BASE = 'https://prod.danawa.com/info/?pcode=';

const HEADERS = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/122 Safari/537.36',
  'Referer': 'https://prod.danawa.com/list/?cate=112758',
  'Accept-Language': 'ko-KR,ko;q=0.9',
};

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/** Slugify a Korean + English brand/model string */
function toSlug(str) {
  return str
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-');
}

/** Detect brand from name */
function detectBrand(name) {
  const lower = name.toLowerCase();
  if (lower.includes('삼성') || lower.includes('samsung') || lower.includes('galaxy book')) return 'samsung';
  if (lower.includes('lg') || lower.includes('그램') || lower.includes('gram')) return 'lg';
  if (lower.includes('apple') || lower.includes('macbook')) return 'apple';
  if (lower.includes('lenovo') || lower.includes('thinkpad') || lower.includes('ideapad') || lower.includes('yoga')) return 'lenovo';
  if (lower.includes('asus') || lower.includes('vivobook') || lower.includes('zenbook') || lower.includes('rog')) return 'asus';
  if (lower.includes('dell') || lower.includes('xps') || lower.includes('inspiron')) return 'dell';
  if (lower.includes('hp') || lower.includes('엔비') || lower.includes('envy') || lower.includes('spectre') || lower.includes('pavilion')) return 'hp';
  if (lower.includes('acer') || lower.includes('swift') || lower.includes('aspire') || lower.includes('nitro')) return 'acer';
  if (lower.includes('microsoft') || lower.includes('surface')) return 'microsoft';
  if (lower.includes('msi')) return 'msi';
  if (lower.includes('razer')) return 'razer';
  return 'unknown';
}

/** Detect CPU series from CPU model string */
function detectCpuSeries(cpu) {
  const lower = cpu.toLowerCase();
  if (lower.includes('m3')) return 'apple-m3';
  if (lower.includes('m2')) return 'apple-m2';
  if (lower.includes('m1')) return 'apple-m1';
  if (lower.includes('i9')) return 'intel-core-i9';
  if (lower.includes('i7')) return 'intel-core-i7';
  if (lower.includes('i5')) return 'intel-core-i5';
  if (lower.includes('i3')) return 'intel-core-i3';
  if (lower.includes('ryzen 9')) return 'amd-ryzen-9';
  if (lower.includes('ryzen 7')) return 'amd-ryzen-7';
  if (lower.includes('ryzen 5')) return 'amd-ryzen-5';
  if (lower.includes('ryzen 3')) return 'amd-ryzen-3';
  return 'other';
}

/** Guess use cases from specs */
function guessUseCases(brand, cpu, gpu, weightKg, priceKrw) {
  const uses = [];
  const cpuLower = cpu.toLowerCase();
  const gpuLower = gpu.toLowerCase();

  if (gpuLower.includes('rtx') || gpuLower.includes('rx 6') || gpuLower.includes('rx 7')) {
    uses.push('gaming');
  }
  if (priceKrw < 800000) uses.push('student', 'everyday');
  if (weightKg < 1.4) uses.push('ultraportable');
  if (brand === 'apple') uses.push('creative', 'programming');
  if (cpuLower.includes('i7') || cpuLower.includes('i9') || cpuLower.includes('ryzen 7') || cpuLower.includes('ryzen 9')) {
    if (!uses.includes('gaming')) uses.push('creative');
