  if (!uses.length) uses.push('everyday');
  return [...new Set(uses)];
}

/** Guess tags from specs */
function guessTags(displayType, weightKg, gpu, priceKrw, useCases) {
  const tags = [];
  if (displayType === 'OLED') tags.push('oled');
  if (weightKg < 1.3) tags.push('lightweight', 'thin-light');
  if (gpu.toLowerCase().includes('rtx') || gpu.toLowerCase().includes('rx ')) tags.push('discrete-gpu');
