  while ((sm = specRe.exec(html)) !== null) {
    specMap[sm[1].trim()] = sm[2].trim();
  }

  const cpu = specMap['CPU'] || specMap['프로세서'] || 'Unknown CPU';
  const ramRaw = specMap['메모리'] || specMap['RAM'] || '8GB';
  const ramGb = parseInt(ramRaw) || 8;
  const storageRaw = specMap['저장장치'] || specMap['SSD'] || '256GB';
  const storageGb = parseInt(storageRaw) || 256;
  const storageType = storageRaw.toLowerCase().includes('nvme') ? 'NVMe' : 'SSD';
  const displayRaw = specMap['화면 크기'] || specMap['디스플레이'] || '15.6인치';
  const displayInch = parseFloat(displayRaw) || 15.6;
  const displayTypeRaw = (specMap['패널 종류'] || '').toUpperCase();
  const displayType = displayTypeRaw.includes('OLED') ? 'OLED' : displayTypeRaw.includes('IPS') ? 'IPS' : 'IPS';
  const weightRaw = specMap['무게'] || '1.8kg';
  const weightKg = parseFloat(weightRaw) || 1.8;
  const gpu = specMap['GPU'] || specMap['그래픽'] || 'Integrated';
  const batteryRaw = specMap['배터리'] || '50Wh';
  const batteryWh = parseFloat(batteryRaw) || 50;
  const year = new Date().getFullYear();

  const brand = detectBrand(name);
  const slug = `${toSlug(brand)}-${toSlug(name).slice(0, 40)}-${pcode}`.replace(/-+/g, '-');
