  const useCases = guessUseCases(brand, cpu, gpu, weightKg, price);
  const tags = guessTags(displayType, weightKg, gpu, price, useCases);

  return {
    id: parseInt(pcode, 10),
    slug,
    brand,
    model: name,
    year,
    price_krw: price,
    refurlab_url: `https://refurlab.com/search?q=${encodeURIComponent(name)}`,
    cpu,
    cpu_series: cpuSeries,
    ram_gb: ramGb,
    storage_gb: storageGb,
    storage_type: storageType,
    display_inch: displayInch,
    display_type: displayType,
    display_resolution: '1920x1080',
    gpu,
    battery_wh: batteryWh,
    weight_kg: weightKg,
    os: brand === 'apple' ? 'macOS' : 'Windows 11 Home',
    meta_title: `${name} 상세 스펙 | LaptopFYI`,
    meta_description: `${name} 상세 스펙, 가격, 리뷰 정보. ${cpu}, ${ramGb}GB RAM, ${storageGb}GB ${storageType}.`,
    use_cases: useCases,
    tags,
  };
}

// ─── Main ────────────────────────────────────────────────────────────────────

const args = process.argv.slice(2);
const maxPages = parseInt(args[args.indexOf('--pages') + 1] || '5') || 5;
const outFile = args[args.indexOf('--out') + 1] || 'data/laptops-crawled.json';

console.log(`Crawling Danawa — ${maxPages} pages → ${outFile}`);

const results = [];
const seenCodes = new Set();

for (let page = 1; page <= maxPages; page++) {
  console.log(`  [${page}/${maxPages}] Fetching list page...`);
  let html;
  try {
    html = await fetchListPage(page);
  } catch (e) {
    console.error(`  List page ${page} failed:`, e.message);
    break;
  }

  const codes = parseProductCodes(html);
  console.log(`  Found ${codes.length} product codes`);

  for (const code of codes) {
    if (seenCodes.has(code)) continue;
    seenCodes.add(code);

    await sleep(DELAY_MS);
    try {
      const detail = await fetchDetailPage(code);
      const product = parseDetail(detail, code);
      if (product.price_krw > 0) {
        results.push(product);
        process.stdout.write(`    ✓ ${product.brand} ${product.model.slice(0, 30)}\n`);
      }
    } catch (e) {
      console.error(`    ✗ pcode ${code}:`, e.message);
    }
  }

  await sleep(DELAY_MS * 2);
}

const outPath = path.resolve(outFile);
fs.writeFileSync(outPath, JSON.stringify(results, null, 2), 'utf-8');
console.log(`\nDone. ${results.length} products saved to ${outPath}`);
console.log('Review the file then merge into data/laptops.json manually.');
